#!/usr/bin/env bun
/**
 * Generates platform files from brand/tokens.json (the single source of truth, spec §8.1):
 *   - brand/generated/tokens.css         CSS variables + shadcn/ui aliases (light, dark)
 *   - brand/generated/HarveyTokens.swift SwiftUI constants for the widget (dynamic light/dark)
 *
 * Usage:
 *   bun brand/build-tokens.ts           write the generated files
 *   bun brand/build-tokens.ts --check   exit 1 if they are missing or out of date
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { join } from "node:path";

type Pair = { light: string; dark: string; description?: string };
type ListColour = { light: { fg: string; bg: string }; dark: { fg: string; bg: string } };
type TextStyle = {
  font: "ui" | "lecture" | "mono";
  size: number;
  lineHeight: number;
  weight: number;
  letterSpacing?: string;
  transform?: string;
  maxWidth?: number;
};
type Tokens = {
  meta: { name: string; version: string };
  color: Record<string, Record<string, Pair>>;
  palette: { neutre: Record<string, string>; liste: Record<string, ListColour | string> };
  font: Record<string, { family: string; fallback: string[] }>;
  text: Record<string, TextStyle>;
  radius: Record<string, number>;
  space: Record<string, number>;
  shadow: Record<string, string>;
  motion: { duration: number; easing: string };
  shadcn: Record<string, string>;
};

const BRAND_DIR = import.meta.dir;
const OUT_DIR = join(BRAND_DIR, "generated");
const HEX = /^#[0-9A-F]{6}$/;
const HEADER = "Generated by brand/build-tokens.ts from brand/tokens.json. Do not edit by hand.";

const tokens: Tokens = JSON.parse(readFileSync(join(BRAND_DIR, "tokens.json"), "utf8"));

// ---------- validation ----------
const errors: string[] = [];
const checkHex = (path: string, value: string) => {
  if (!HEX.test(value)) errors.push(`${path}: "${value}" is not an uppercase #RRGGBB colour`);
};
for (const [group, entries] of Object.entries(tokens.color)) {
  for (const [name, pair] of Object.entries(entries)) {
    checkHex(`color.${group}.${name}.light`, pair.light);
    checkHex(`color.${group}.${name}.dark`, pair.dark);
  }
}
for (const [step, value] of Object.entries(tokens.palette.neutre)) checkHex(`palette.neutre.${step}`, value);
const listColours = Object.entries(tokens.palette.liste).filter(
  (entry): entry is [string, ListColour] => !entry[0].startsWith("$"),
);
for (const [name, c] of listColours) {
  for (const mode of ["light", "dark"] as const) {
    checkHex(`palette.liste.${name}.${mode}.fg`, c[mode].fg);
    checkHex(`palette.liste.${name}.${mode}.bg`, c[mode].bg);
  }
}
const shadcn = Object.entries(tokens.shadcn).filter(([key]) => !key.startsWith("$"));
for (const [key, ref] of shadcn) {
  const [group, name] = ref.split(".");
  if (!tokens.color[group]?.[name]) errors.push(`shadcn.${key}: unknown colour token "${ref}"`);
}
for (const [name, style] of Object.entries(tokens.text)) {
  if (!tokens.font[style.font]) errors.push(`text.${name}: unknown font "${style.font}"`);
}
if (errors.length) {
  console.error(`brand/tokens.json is invalid:\n  ${errors.join("\n  ")}`);
  process.exit(1);
}

// ---------- CSS ----------
const colourEntries = Object.entries(tokens.color).flatMap(([group, entries]) =>
  Object.entries(entries).map(([name, pair]) => ({ variable: `--${group}-${name}`, pair })),
);
const colourBlock = (mode: "light" | "dark", indent: string) => [
  ...colourEntries.map(({ variable, pair }) => `${indent}${variable}: ${pair[mode]};`),
  ...listColours.flatMap(([name, c]) => [
    `${indent}--liste-${name}: ${c[mode].fg};`,
    `${indent}--liste-${name}-fond: ${c[mode].bg};`,
  ]),
];
const fontStack = (key: string) => {
  const f = tokens.font[key];
  return [`"${f.family}"`, ...f.fallback.map((x) => (x.includes(" ") ? `"${x}"` : x))].join(", ");
};

const textStyleVars = Object.entries(tokens.text).flatMap(([name, t]) => {
  const v = `  --texte-${name}`;
  return [
    `${v}-police: var(--font-${t.font});`,
    `${v}-taille: ${t.size}px;`,
    `${v}-interligne: ${t.lineHeight}px;`,
    `${v}-graisse: ${t.weight};`,
    ...(t.letterSpacing ? [`${v}-approche: ${t.letterSpacing};`] : []),
    ...(t.transform ? [`${v}-casse: ${t.transform};`] : []),
    ...(t.maxWidth ? [`${v}-largeur-max: ${t.maxWidth}px;`] : []),
  ];
});

const css = [
  `/* ${HEADER} */`,
  `/* ${tokens.meta.name} tokens v${tokens.meta.version} */`,
  "",
  "/* Light (default) */",
  ":root {",
  "  color-scheme: light;",
  ...colourBlock("light", "  "),
  "",
  ...Object.entries(tokens.palette.neutre).map(([step, v]) => `  --neutre-${step}: ${v};`),
  "",
  ...Object.keys(tokens.font).map((key) => `  --font-${key}: ${fontStack(key)};`),
  ...Object.entries(tokens.radius).map(([k, v]) => `  --rayon-${k}: ${v}px;`),
  ...Object.entries(tokens.space).map(([k, v]) => `  --espace-${k}: ${v}px;`),
  ...Object.entries(tokens.shadow).map(([k, v]) => `  --ombre-${k}: ${v};`),
  `  --duree: ${tokens.motion.duration}ms;`,
  `  --courbe: ${tokens.motion.easing};`,
  "",
  "  /* Text styles */",
  ...textStyleVars,
  "",
  "  /* shadcn/ui */",
  ...shadcn.map(([key, ref]) => `  --${key}: var(--${ref.replace(".", "-")});`),
  `  --radius: ${tokens.radius.moyen}px;`,
  "}",
  "",
  "/* Dark: follows macOS unless the app forces a theme with data-theme */",
  "@media (prefers-color-scheme: dark) {",
  '  :root:not([data-theme="light"]) {',
  "    color-scheme: dark;",
  ...colourBlock("dark", "    "),
  "  }",
  "}",
  '[data-theme="dark"] {',
  "  color-scheme: dark;",
  ...colourBlock("dark", "  "),
  "}",
  "",
  "@media (prefers-reduced-motion: reduce) {",
  "  :root {",
  "    --duree: 0ms;",
  "  }",
  "}",
  "",
].join("\n");

// ---------- Swift ----------
const camel = (s: string) => s.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase());
const hex = (v: string) => `0x${v.slice(1)}`;
const swiftWeight: Record<number, string> = { 400: ".regular", 500: ".medium", 600: ".semibold" };

const swift = [
  `// ${HEADER}`,
  `// ${tokens.meta.name} tokens v${tokens.meta.version}`,
  "",
  "import AppKit",
  "import SwiftUI",
  "",
  "public enum HarveyTokens {",
  "    public enum Colors {",
  ...colourEntries.map(({ variable, pair }) => {
    const name = camel(variable.slice(2));
    const doc = pair.description ? `        /// ${pair.description}\n` : "";
    return `${doc}        public static let ${name} = dynamic(light: ${hex(pair.light)}, dark: ${hex(pair.dark)})`;
  }),
  "    }",
  "",
  "    public enum Liste {",
  ...listColours.flatMap(([name, c]) => [
    `        public static let ${camel(name)} = dynamic(light: ${hex(c.light.fg)}, dark: ${hex(c.dark.fg)})`,
    `        public static let ${camel(name)}Fond = dynamic(light: ${hex(c.light.bg)}, dark: ${hex(c.dark.bg)})`,
  ]),
  "    }",
  "",
  "    public enum Radius {",
  ...Object.entries(tokens.radius).map(([k, v]) => `        public static let ${camel(k)}: CGFloat = ${v}`),
  "    }",
  "",
  "    public enum Space {",
  ...Object.entries(tokens.space).map(([k, v]) => `        public static let s${k}: CGFloat = ${v}`),
  "    }",
  "",
  "    public enum FontFamily {",
  ...Object.entries(tokens.font).map(([k, f]) => `        public static let ${camel(k)} = "${f.family}"`),
  "    }",
  "",
  "    public enum Text {",
  ...Object.entries(tokens.text).map(([k, t]) => {
    const family = camel(t.font);
    return `        public static let ${camel(k)} = Font.custom(FontFamily.${family}, fixedSize: ${t.size}).weight(${swiftWeight[t.weight] ?? ".regular"})`;
  }),
  "    }",
  "",
  "    /// A colour that resolves to the light or dark value from the current appearance.",
  "    static func dynamic(light: UInt32, dark: UInt32) -> SwiftUI.Color {",
  "        SwiftUI.Color(nsColor: NSColor(name: nil) { appearance in",
  "            let isDark = appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua",
  "            return NSColor(harveyHex: isDark ? dark : light)",
  "        })",
  "    }",
  "}",
  "",
  "extension NSColor {",
  "    convenience init(harveyHex hex: UInt32) {",
  "        self.init(",
  "            srgbRed: CGFloat((hex >> 16) & 0xFF) / 255,",
  "            green: CGFloat((hex >> 8) & 0xFF) / 255,",
  "            blue: CGFloat(hex & 0xFF) / 255,",
  "            alpha: 1",
  "        )",
  "    }",
  "}",
  "",
].join("\n");

// ---------- write / check ----------
const outputs: Record<string, string> = {
  "tokens.css": css,
  "HarveyTokens.swift": swift,
};

if (process.argv.includes("--check")) {
  const stale = Object.entries(outputs)
    .filter(([file, content]) => {
      const path = join(OUT_DIR, file);
      return !existsSync(path) || readFileSync(path, "utf8") !== content;
    })
    .map(([file]) => file);
  if (stale.length) {
    console.error(`Out of date: ${stale.join(", ")}. Run: bun brand/build-tokens.ts`);
    process.exit(1);
  }
  console.log("brand/generated is up to date.");
} else {
  mkdirSync(OUT_DIR, { recursive: true });
  for (const [file, content] of Object.entries(outputs)) {
    writeFileSync(join(OUT_DIR, file), content);
    console.log(`wrote brand/generated/${file}`);
  }
}
